async function createPayment(input: PaymentInput, key: string) {
  const existing = await db.idempotency.findUnique({ where: { key } });
  if (existing) return existing.response;

  const payment = await db.payment.create({ data: input });
  await db.idempotency.create({ data: { key, response: payment } });
  return payment;
}

async function handle(entry: Entry) {
  await doBusinessChange(entry.payload);
  await redis.xAck('jobs', 'workers', entry.id);
}

async function poll() {
  const entries = await redis.xReadGroup('workers', 'alice', { key: 'jobs', id: '>' });
  for (const entry of entries) {
    await handle(entry);
  }
}

async function createOrder(input: OrderInput) {
  const order = await db.orders.insert(input);
  await broker.publish({ type: 'order.created', orderId: order.id });
  return order;
}
